const a="templates/index.json";
const b="/api/generate-image";
let c=null;
async function d(){
const h=await fetch(a);
const i=await h.json();
const j=document.getElementById("template");
for(const l of i.templates){
const k=document.createElement("option");
k.value=l.file;
k.textContent=l.name;
j.appendChild(k);
}
j.addEventListener("change",function(){e(j.value);});
await e(i.templates[0].file);
}
async function e(s){
const h=await fetch(s);
c=await h.json();
f();
}
function f(){
const m=document.getElementById("card");
const n=document.getElementById("title").value.slice(0,c.title.maxChars);
const o=document.getElementById("body").value.slice(0,c.body.maxChars);
m.innerHTML="";
const p=document.createElement("h2");
p.textContent=n;
p.style.color=c.title.color;
const q=document.createElement("p");
q.textContent=o;
q.style.color=c.body.color;
m.appendChild(p);
m.appendChild(q);
}
async function g(){
const r=document.getElementById("prompt").value;
const h=await fetch(b,{
method:"POST",
headers:{"Content-Type":"application/json"},
body:JSON.stringify({prompt:r,template:c.id})
});
const t=await h.text();
const m=document.getElementById("card");
m.style.backgroundImage="url(\"data:image/svg+xml;charset=utf-8,"+encodeURIComponent(t)+"\")";
}
document.getElementById("title").addEventListener("input",f);
document.getElementById("body").addEventListener("input",f);
document.getElementById("make-bg").addEventListener("click",g);
d();
